-- Esquema mínimo de pruebas locales. Las migraciones comerciales son reales.
CREATE ROLE authenticated; CREATE ROLE anon; CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('app.test_user',true),'')::uuid $$;
CREATE TABLE comercio(id uuid PRIMARY KEY);
CREATE TABLE comercio_usuarios(comercio_id uuid,user_id uuid,rol text,activo boolean);
CREATE TABLE comercio_parametrizacion(comercio_id uuid PRIMARY KEY,parametros jsonb,updated_at timestamptz DEFAULT now());
CREATE FUNCTION public.user_belongs_to_comercio(p_id uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM comercio_usuarios WHERE comercio_id=p_id AND user_id=auth.uid() AND activo) $$;
CREATE FUNCTION public.user_is_comercio_admin(p_id uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT EXISTS(SELECT 1 FROM comercio_usuarios WHERE comercio_id=p_id AND user_id=auth.uid() AND activo AND rol='admin') $$;
CREATE FUNCTION public.update_updated_at_column() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE FUNCTION public.set_comercio_id_from_context() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
CREATE TYPE tipo_pago AS ENUM ('contado','transferencia','tarjeta','cheque','cta_cte','mercado_pago');
CREATE TYPE tipo_comprobante AS ENUM ('recibo_x','factura_a','factura_b','factura_c','nota_credito_a');
CREATE TABLE clientes(id uuid PRIMARY KEY,comercio_id uuid,nombre text,apellido text,cuit text);
CREATE TABLE proveedores(id uuid PRIMARY KEY,comercio_id uuid);
CREATE TABLE productos(id uuid PRIMARY KEY,comercio_id uuid,stock integer CHECK(stock>=0),tipo_moneda text DEFAULT 'ARS');
CREATE TABLE producto_variantes(id uuid PRIMARY KEY,producto_id uuid REFERENCES productos(id),stock integer CHECK(stock>=0));
CREATE TABLE bancos(id uuid PRIMARY KEY,comercio_id uuid);
CREATE TABLE tarjetas_credito(id uuid PRIMARY KEY,comercio_id uuid);
CREATE TABLE cheques(id uuid PRIMARY KEY,comercio_id uuid);
CREATE TABLE afip_config(comercio_id uuid,punto_venta integer,activo boolean);
CREATE TABLE ventas_numeradores(comercio_id uuid,tipo_comprobante tipo_comprobante,punto_venta integer,ultimo_numero bigint,updated_at timestamptz,PRIMARY KEY(comercio_id,tipo_comprobante,punto_venta));
CREATE TABLE ventas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),comercio_id uuid,numero_comprobante text,fecha_venta timestamptz,tipo_pago tipo_pago,tipo_comprobante tipo_comprobante,cliente_id uuid,cliente_nombre text,moneda text,punto_venta integer,numero_secuencial bigint,origen_orden_trabajo boolean DEFAULT false,porcentaje_descuento numeric,monto_descuento numeric,porcentaje_recargo numeric,monto_recargo numeric,subtotal numeric,total_iva numeric,total numeric,observaciones text,cae text,UNIQUE(comercio_id,tipo_comprobante,punto_venta,numero_secuencial));
CREATE TABLE venta_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venta_id uuid REFERENCES ventas(id),comercio_id uuid,producto_id uuid,producto_variante_id uuid,descripcion_manual text,codigo_manual text,cantidad numeric,precio_unitario numeric,porcentaje_iva numeric,porcentaje_descuento numeric,monto_descuento numeric,porcentaje_recargo numeric,monto_recargo numeric,monto_iva numeric,subtotal numeric,total numeric,afecta_stock boolean DEFAULT true,CHECK((producto_id IS NOT NULL AND afecta_stock AND cantidad=trunc(cantidad)) OR (producto_id IS NULL AND NOT afecta_stock)));
CREATE TABLE pagos_venta(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venta_id uuid REFERENCES ventas(id),comercio_id uuid,tipo_pago tipo_pago,monto numeric,banco_id uuid,tarjeta_id uuid,cuotas integer,recargo_cuotas numeric,cheque_id uuid,moneda text);
CREATE TABLE cuenta_corriente(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),comercio_id uuid,cliente_id uuid,tipo_movimiento text,monto numeric,concepto text,venta_id uuid,fecha_movimiento timestamptz,moneda text);
CREATE FUNCTION test_assert(p_ok boolean,p_label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF p_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Assertion failed: %',p_label; END IF; END $$;
CREATE FUNCTION test_error(p_sql text,p_error text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE p_sql; EXCEPTION WHEN OTHERS THEN IF position(p_error IN SQLERRM)>0 THEN RETURN; END IF; RAISE; END; RAISE EXCEPTION 'Expected rejection: %',p_error; END $$;
GRANT USAGE ON SCHEMA public,auth TO authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
